import { expect, expectStatus, test, type APIRequestContext } from "../../fixtures";

type DocumentKind = "w9" | "insurance_certificate" | "contract";

interface DocumentOut {
  id: string;
  vendor_id: string;
  kind: DocumentKind;
  status: "processing" | "extracted" | "failed";
}

interface ExtractionOut {
  id: string;
  document_id: string;
  kind: DocumentKind;
  status: "pending_review" | "approved" | "rejected";
}

interface VendorOut {
  id: string;
  status: "draft" | "in_review" | "approved" | "rejected";
}

interface ReviewQueueItem {
  vendor_id: string;
  extractions: ExtractionOut[];
}

const POLL_ATTEMPTS = 60;
const POLL_INTERVAL_MS = 500;

function uniqueSuffix(): string {
  return `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

async function uploadDocument(
  member: APIRequestContext,
  vendorId: string,
  kind: DocumentKind,
  suffix: string,
): Promise<DocumentOut> {
  const response = await member.post(`/api/vendors/${vendorId}/documents`, {
    multipart: {
      kind,
      file: {
        name: `${kind}-${suffix}.pdf`,
        mimeType: "application/pdf",
        buffer: Buffer.from(`%PDF-1.4 LIF-05 ${kind} ${suffix}`),
      },
    },
  });
  return expectStatus<DocumentOut>(response, 201);
}

/** Polls the document until extraction finishes, then returns its extraction. */
async function waitForExtraction(api: APIRequestContext, documentId: string): Promise<ExtractionOut> {
  for (let attempt = 0; attempt < POLL_ATTEMPTS; attempt++) {
    const document = await expectStatus<DocumentOut>(await api.get(`/api/documents/${documentId}`), 200);
    if (document.status === "failed") {
      throw new Error(`extraction failed for document ${documentId}`);
    }
    if (document.status === "extracted") {
      return expectStatus<ExtractionOut>(await api.get(`/api/documents/${documentId}/extraction`), 200);
    }
    await new Promise((resolve) => setTimeout(resolve, POLL_INTERVAL_MS));
  }
  throw new Error(`document ${documentId} was not extracted within the polling window`);
}

test.describe("vendor lifecycle", () => {
  test(
    "after a replacement, only the new document waits for review",
    { tag: "@LIF-05" },
    async ({ apiAs }) => {
      // Arrange: a vendor with approved insurance and contract extractions and a rejected w9.
      const member = await apiAs("member");
      const reviewer = await apiAs("reviewer");
      const suffix = uniqueSuffix();

      const vendor = await expectStatus<VendorOut>(
        await member.post("/api/vendors", {
          data: {
            name: `LIF-05 Replacement ${suffix}`,
            category: "services",
            contact_email: `lif-05-${suffix}@vendor.test`,
          },
        }),
        201,
      );

      const insurance = await uploadDocument(member, vendor.id, "insurance_certificate", suffix);
      const contract = await uploadDocument(member, vendor.id, "contract", suffix);
      const w9 = await uploadDocument(member, vendor.id, "w9", suffix);

      const insuranceExtraction = await waitForExtraction(member, insurance.id);
      const contractExtraction = await waitForExtraction(member, contract.id);
      const w9Extraction = await waitForExtraction(member, w9.id);

      await expectStatus<VendorOut>(await member.post(`/api/vendors/${vendor.id}/submit`), 200);

      await expectStatus(
        await reviewer.post(`/api/extractions/${insuranceExtraction.id}/decision`, {
          data: { decision: "approve" },
        }),
        200,
      );
      await expectStatus(
        await reviewer.post(`/api/extractions/${contractExtraction.id}/decision`, {
          data: { decision: "approve" },
        }),
        200,
      );
      await expectStatus(
        await reviewer.post(`/api/extractions/${w9Extraction.id}/decision`, {
          data: { decision: "reject", note: `LIF-05 rejected w9 ${suffix}` },
        }),
        200,
      );

      // Act: upload a replacement w9, wait for extraction, and resubmit.
      const replacementW9 = await uploadDocument(member, vendor.id, "w9", `${suffix}-replacement`);
      await waitForExtraction(member, replacementW9.id);
      const resubmitted = await expectStatus<VendorOut>(
        await member.post(`/api/vendors/${vendor.id}/submit`),
        200,
      );

      // Assert: the vendor is back in review.
      expect(resubmitted.id).toBe(vendor.id);
      expect(resubmitted.status).toBe("in_review");

      // Assert: the review queue shows exactly one pending extraction, the new w9.
      const queue = await expectStatus<ReviewQueueItem[]>(await reviewer.get("/api/review-queue"), 200);
      const item = queue.find((entry) => entry.vendor_id === vendor.id);
      expect(item, "vendor should appear in the review queue").toBeDefined();

      const pending = item!.extractions.filter((extraction) => extraction.status === "pending_review");
      expect(pending).toHaveLength(1);
      expect(pending[0].kind).toBe("w9");
    },
  );
});
